// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 timestamp1, uint256 timestamp2) public {
        timestamp1 = bound(timestamp1, 0, type(uint64).max);
        timestamp2 = bound(timestamp2, 0, type(uint64).max);

        vm.assume(timestamp1 != timestamp2);

        address actor = address(0x100);
        vm.deal(actor, 10 ether);

        vm.warp(timestamp1);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");

        uint256 oldPast = c.pastBlockTime();

        vm.warp(timestamp2);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        if (ok1 && ok2) {
            assertTrue(c.pastBlockTime() > oldPast);
        } else {
            assertTrue(true);
        }
    }
}
